import math

def _square_free_factor(D):
    m = abs(D)
    s = 1
    i = 2
    while i * i <= m:
        sq = i * i
        while m % sq == 0:
            s *= i
            m //= sq
        i += 1
    n = m
    return s, n


def _gcd3(a, b, c):
    return math.gcd(math.gcd(abs(a), abs(b)), abs(c))


def verifier(assign):
    # Validate domain constraints and recompute the answer
    a = assign.get('ab_len')
    c = assign.get('cd_len')
    b = assign.get('leg_len')
    RA = assign.get('r_top')
    RC = assign.get('r_bottom')
    # Basic checks
    if not all(isinstance(x, int) for x in [a, c, b, RA, RC]):
        # invalid types
        return (False, None)
    if not (a > c >= 1 and b >= 1 and RA >= 1 and RC >= 1):
        return (False, None)
    # Geometry setup
    d = (a - c) / 2.0
    h2 = b * b - d * d
    if h2 <= 0:
        # invalid trapezoid
        return (False, None)
    H = math.sqrt(h2)
    if RA == RC:
        # symmetry degeneracy for uniqueness (tangent circle family would be ambiguous)
        return (False, None)
    dR = RA - RC
    T = 4 * b * b - (a - c) * (a - c)  # 4H^2
    E4 = 4 * b * b + 2 * a * c - 4 * RA * RA + 4 * RC * RC
    A_int = 16 * dR * dR - 4 * T
    if A_int == 0:
        return (False, None)
    B_int = -4 * E4 * dR - 2 * T * RC
    C_int = (E4 * E4) // 4 - T * RC * RC + T * c * c
    D_int = B_int * B_int - 4 * A_int * C_int
    if D_int <= 0:
        return (False, None)
    # Nontrivial radical requirement
    if math.isqrt(D_int) ** 2 == D_int:
        return (False, None)
    sqrtD = math.sqrt(D_int)
    x_candidates = [(-B_int + sqrtD) / (2.0 * A_int), (-B_int - sqrtD) / (2.0 * A_int)]
    chosen = None
    used_plus_branch = None
    for idx, x in enumerate(x_candidates):
        if x <= 1e-12:
            continue
        if RA + x < a / 2.0 - 1e-9:
            continue
        if RC + x < c / 2.0 - 1e-9:
            continue
        val = (RC + x) ** 2 - (c / 2.0) ** 2
        if val <= 1e-12:
            continue
        y = math.sqrt(val)
        d_top = H - y
        d_bottom = y
        s2 = 2.0 * H / (a + c)
        d_leg = abs(y - H + s2 * a / 2.0) / math.sqrt(1.0 + s2 * s2)
        mnd = min(d_top, d_bottom, d_leg)
        if mnd <= x + 1e-9:
            continue
        if not (y > 0 and y < H):
            continue
        chosen = (x, y)
        used_plus_branch = (idx == 0)
        break
    if chosen is None:
        return (False, None)
    x, y = chosen
    # Build canonical radical representation
    s, n = _square_free_factor(D_int)
    denom = 2 * A_int
    numer_const = -B_int
    numer_rad = s if used_plus_branch else -s
    g = _gcd3(numer_const, denom, numer_rad)
    sign = 1 if denom > 0 else -1
    p = (abs(denom) // g)
    u = (numer_const * sign) // g
    v = (numer_rad * sign) // g
    # Validate lowest terms and square-free
    if _gcd3(u, v, p) != 1:
        return (False, None)
    ok_sqfree = True
    i = 2
    while i * i <= n:
        if n % (i * i) == 0:
            ok_sqfree = False
            break
        i += 1
    if not ok_sqfree:
        return (False, None)
    # Final answer
    answer = u + v + n + p
    return (True, answer)
